"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["23703"],{52039(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.fato_nao_coletavel","status":422,"titulo":"O dado do candidato do item n\xe3o \xe9 colet\xe1vel num campo"},"descricao":{"codigo":"uniplus.item_formulario.fato_nao_coletavel","requisitos":["UNI-REQ-0143","UNI-REQ-0146"],"oQueAconteceu":["O dado do candidato existe no cat\xe1logo, mas n\xe3o pode ser coletado no campo em que foi posto. S\xf3 o dado que o pr\xf3prio candidato responde, declarado no formul\xe1rio, vai num campo comum. O dado derivado (obtido de outros dados por uma regra) e o dado calculado (obtido pelo sistema) n\xe3o s\xe3o respondidos pelo candidato (UNI-REQ-0143). O dado de membro de grupo \xe9 respondido por cada membro, e por isso s\xf3 existe dentro de um grupo repet\xedvel, onde cada ocorr\xeancia responde o seu (UNI-REQ-0146). A mensagem nomeia o dado como aparece no cat\xe1logo (`{nome\\\\}`), sem repetir o c\xf3digo, e diz qual \xe9 a situa\xe7\xe3o:","- no item do formul\xe1rio: \\"O dado do candidato \'`{nome\\\\}`\' n\xe3o \xe9 colet\xe1vel num campo: s\xf3 o dado declarado do pr\xf3prio candidato \xe9 respondido no formul\xe1rio \u2014 dados derivados, calculados e de membro de grupo n\xe3o.\\";\\n- no campo de um grupo: \\"O dado do candidato \'`{nome\\\\}`\' n\xe3o \xe9 colet\xe1vel num campo do grupo: s\xf3 o dado declarado de membro de grupo \xe9 respondido em cada ocorr\xeancia \u2014 dados do pr\xf3prio candidato, derivados e calculados n\xe3o.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].fatoCodigo` ou `grupos[g].subitens[j].fatoCodigo`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`, e o pressuposto que nomeia um dado n\xe3o colet\xe1vel \xe9 recusado em `conteudo.pressupostos[i]`. O item cuja forma b\xe1sica j\xe1 foi recusada n\xe3o chega a esta confer\xeancia. Nada \xe9 gravado.","Na aplica\xe7\xe3o de um modelo ao processo, o item ou o grupo cujo dado deixou de ser colet\xe1vel depois da composi\xe7\xe3o do modelo n\xe3o \xe9 recusado: sai da c\xf3pia e volta no relat\xf3rio da aplica\xe7\xe3o, entre as partes descartadas. Na atualiza\xe7\xe3o de um modelo, um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Coloque no campo comum do formul\xe1rio s\xf3 um dado que o pr\xf3prio candidato responde, e no campo de um grupo s\xf3 um dado de membro de grupo. O dado derivado ou calculado chega \xe0s regras do formul\xe1rio por cita\xe7\xe3o, e n\xe3o por um campo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);